{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title_h1",
        "subtitle_h2",
        "itinerary_table",
        "budget_summary_h2",
        "budget_table",
        "checklist_h2",
        "checklist_stack",
        "quick_actions_h2",
        "quick_actions_stack"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Tokyo Tech & Tradition Expedition",
        "variant": "h1"
      },
      "children": []
    },
    "subtitle_h2": {
      "type": "Text",
      "props": {
        "text": "4-Day Anime & Heritage Itinerary",
        "variant": "h2"
      },
      "children": []
    },
    "itinerary_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "day",
            "label": "Day"
          },
          {
            "key": "title",
            "label": "Area"
          },
          {
            "key": "morning",
            "label": "Morning"
          },
          {
            "key": "afternoon",
            "label": "Afternoon"
          },
          {
            "key": "evening",
            "label": "Evening"
          },
          {
            "key": "actionLabel",
            "label": "Guide"
          }
        ],
        "rows": [
          {
            "day": "Day 1",
            "title": "Historic Asakusa & Sumida",
            "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/67/Sens%C5%8D-ji_temple_at_night.jpg/1200px-Sens%C5%8D-ji_temple_at_night.jpg",
            "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/building.svg",
            "morning": "Explore Senso-ji, Tokyo's oldest temple, and Nakamise shopping street.",
            "afternoon": "Take a scenic Sumida River cruise to Odaiba for futuristic waterfront views.",
            "evening": "Traditional Izakaya dinner in the atmospheric alleys of Hoppy Street.",
            "actionLabel": "Asakusa Guide",
            "actionUrl": "https://www.japan-guide.com/e/e3001.html"
          },
          {
            "day": "Day 2",
            "title": "Akihabara Electric Town",
            "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/4b/Akihabara_Electric_Town_2014.jpg/1200px-Akihabara_Electric_Town_2014.jpg",
            "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/laptop.svg",
            "morning": "Visit the Tokyo Anime Center and browse multi-story electronics stores like Yodobashi Camera.",
            "afternoon": "Experience a themed cafe and hunt for retro games at Super Potato.",
            "evening": "Modern ramen dinner followed by high-tech gaming at an arcade.",
            "actionLabel": "Akihabara Map",
            "actionUrl": "https://www.akiba.or.jp/en/"
          }
        ],
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "day",
        "highlightColumns": [
          "title"
        ],
        "entityMedia": {
          "image": {
            "$item": "image"
          },
          "icon": {
            "$item": "icon"
          }
        }
      },
      "children": []
    },
    "budget_summary_h2": {
      "type": "Text",
      "props": {
        "text": "Budget & Logistics Summary",
        "variant": "h2"
      },
      "children": []
    },
    "budget_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "category",
            "label": "Category"
          },
          {
            "key": "cost",
            "label": "Estimated Cost (USD)"
          },
          {
            "key": "notes",
            "label": "Notes"
          }
        ],
        "rows": [
          {
            "category": "Accommodation",
            "cost": "$600",
            "notes": "Stay in Asakusa for budget-friendly ryokans"
          },
          {
            "category": "Food & Dining",
            "cost": "$450",
            "notes": "Mix of street food and sit-down meals"
          },
          {
            "category": "Transport",
            "cost": "$120",
            "notes": "Suica/Pasmo for Metro and JR lines"
          },
          {
            "category": "Activities",
            "cost": "$200",
            "notes": "Entrance fees and arcade gaming"
          },
          {
            "category": "Total",
            "cost": "$1,370",
            "notes": "Within $1,500 Budget"
          }
        ],
        "domain": "formula",
        "preferredPresentation": "table",
        "numericColumns": [
          "cost"
        ]
      },
      "children": []
    },
    "checklist_h2": {
      "type": "Text",
      "props": {
        "text": "Pre-Departure Checklist",
        "variant": "h2"
      },
      "children": []
    },
    "checklist_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "checklist_docs",
        "checklist_weather",
        "checklist_connectivity"
      ]
    },
    "checklist_docs": {
      "type": "Text",
      "props": {
        "text": "Documents: Passport, printed flight/hotel confirmations, Visit Japan Web QR code."
      },
      "children": []
    },
    "checklist_weather": {
      "type": "Text",
      "props": {
        "text": "Weather Prep: Light layers for 15°C–22°C (light jacket, sweaters, umbrella)."
      },
      "children": []
    },
    "checklist_connectivity": {
      "type": "Text",
      "props": {
        "text": "Connectivity: Pocket Wi-Fi or eSIM for navigation and translation apps."
      },
      "children": []
    },
    "quick_actions_h2": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "metro_button",
        "visit_japan_button"
      ]
    },
    "metro_button": {
      "type": "Button",
      "props": {
        "label": "Tokyo Metro Map"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.tokyometro.jp/en/subwaymap/"
          }
        }
      },
      "children": []
    },
    "visit_japan_button": {
      "type": "Button",
      "props": {
        "label": "Visit Japan Web"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://vjw-lp.digital.go.jp/en/"
          }
        }
      },
      "children": []
    }
  }
}
